head.script:
scwin.trigger1_onclick = function(e) {
    var opts = {
        "id": "popup1",
        "type": "litewindow",
        "width": 300 + "px",
        "height": 300 + "px",
        "top": 50,
        "left": 50,
        "popupName": "focusTest",
        "modal": false,
        "useIFrame": true,
        "title": "focusTest"
    };
    WebSquare.util.openPopup("windowContainer_SKT-571_(WSQ-1152)_sub_pop.xml", opts);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
